import React, { useState, useEffect, useContext } from "react";
import axios from "axios";
import {db} from "./"
import CartContext from "./CartContext";
import AuthContext from "./AuthContext";

const sanitizeEmail = (email) => {
  return email.replace(/[@.]/g, "");
};

const fetchCartItems = async (email, setItems) => {
  const sanitizedEmail = sanitizeEmail(email);
  try {
    const cartRef = firebase.database().ref(`carts/${sanitizedEmail}`);
    cartRef.on('value', (snapshot) => {
      const data = snapshot.val();
      if (data) {
        const fetchedItems = Object.values(data).map(item => ({
          ...item,
          quantity: item.quantity || 1 
        }));
        setItems(fetchedItems);
      } else {
        setItems([]);
      }
    });
  } catch (error) {
    console.error('Failed to fetch cart items', error);
  }
};

const CartProvider = (props) => {
  const [isOpenCart, setOpenCart] = useState(false);
  const [items, setItems] = useState([]);
  const authCtx = useContext(AuthContext);

  

  useEffect(() => {
    if (authCtx.userEmail) {
      fetchCartItems(authCtx.userEmail,setItems);
    }
  }, [authCtx.userEmail]);

 

  const openCartHandler = () => {
    setOpenCart(true);
  };

  const closeCartHandler = () => {
    setOpenCart(false);
  };

  // const addItemToCart = async (item) => {
  //   const sanitizedEmail = sanitizeEmail(authCtx.userEmail);
  //   setItems((prevItems) => {
  //     const existingItemIndex = prevItems.findIndex((i) => i.id === item.id);
  //     if (existingItemIndex !== -1) {
  //       const updatedItems = [...prevItems];
  //       updatedItems[existingItemIndex] = {
  //         ...updatedItems[existingItemIndex],
  //         quantity: updatedItems[existingItemIndex].quantity + 1,
  //       };
  //       return updatedItems;
  //     }
  //     return [...prevItems, { ...item, quantity: 1 }];
  //   });

  //   try {
  //     await axios.post(`https://crudcrud.com/api/07b2401bfc4c4ddf950e1671f7eb99b8/cart${sanitizedEmail}`, item);
  //   } catch (error) {
  //     console.error('Failed to add item to cart', error);
  //   }
  // };

  // using firebase rest api 
  const addItemToCart = async (item) => {
    const sanitizedEmail = sanitizeEmail(authCtx.userEmail);
    try {
      const cartRef = firebase.database().ref(`carts/${sanitizedEmail}`);
      await cartRef.push(item);
      
      // Update local state after successful addition
      setItems(prevItems => [
        ...prevItems,
        { ...item, quantity: 1 } // Assuming initial quantity is 1
      ]);
    } catch (error) {
      console.error('Failed to add item to cart', error);
    }
  };
  

  // const removeItemHandler = async (id) => {
  //   const sanitizedEmail = sanitizeEmail(authCtx.userEmail);
  //   setItems((prevItems) => {
  //     const existingItemIndex = prevItems.findIndex((item) => item.id === id);
  //     const existingItem = prevItems[existingItemIndex];
  //     if (existingItem.quantity === 1) {
  //       deleteItemFromApi(id, sanitizedEmail);
  //       return prevItems.filter((item) => item.id !== id);
  //     }
  //     const updatedItems = [...prevItems];
  //     updatedItems[existingItemIndex] = {
  //       ...existingItem,
  //       quantity: existingItem.quantity - 1,
  //     };
  //     return updatedItems;
  //   });
  // };

  // const deleteItemFromApi = async (itemId, email) => {
  //   try {
  //     const response = await axios.get(`https://crudcrud.com/api/07b2401bfc4c4ddf950e1671f7eb99b8/cart${email}`);
  //     const itemToDelete = response.data.find((item) => item.id === itemId);
  //     if (itemToDelete) {
  //       await axios.delete(`https://crudcrud.com/api/07b2401bfc4c4ddf950e1671f7eb99b8/cart${email}/${itemToDelete._id}`);
  //     }
  //   } catch (error) {
  //     console.error('Failed to delete item from cart', error);
  //   }
  // };

    // using firebase api now 
    const removeItemHandler = async (id) => {
      const sanitizedEmail = sanitizeEmail(authCtx.userEmail);
      try {
        const cartRef = firebase.database().ref(`carts/${sanitizedEmail}`);
        const snapshot = await cartRef.once('value');
        snapshot.forEach((childSnapshot) => {
          const childKey = childSnapshot.key;
          const childData = childSnapshot.val();
          if (childData.id === id) {
            cartRef.child(childKey).remove();
            
            // Update local state after successful removal
            setItems(prevItems => prevItems.filter(item => item.id !== id));
          }
        });
      } catch (error) {
        console.error('Failed to remove item from cart', error);
      }
    };
    

  const totalAmount = items.reduce((total, item) => total + item.price * item.quantity, 0);

  const contextObject = {
    items: items,
    isOpenCart,
    totalAmount: totalAmount,
    addItem: addItemToCart,
    removeItem: removeItemHandler,
    openCart: openCartHandler,
    closeCart: closeCartHandler,
  };

  return (
    <CartContext.Provider value={contextObject}>
      {props.children}
    </CartContext.Provider>
  );
};

export default CartProvider;
